import{_ as e,o as n,c as a,aa as o}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/diary/en_import_dochazky2.jpg",p=JSON.parse('{"title":"Project Attendance System","description":"","frontmatter":{"title":"Project Attendance System","wiki":"en:diary:attendance_system"},"headers":[],"relativePath":"en/diary/attendance_system.md","filePath":"en/diary/attendance_system.md","lastUpdated":1795418601000}'),r={name:"en/diary/attendance_system.md"};function i(d,t,l,c,h,m){return n(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="project-attendance-system" tabindex="-1">Project Attendance System <a class="header-anchor" href="#project-attendance-system" aria-label="Permalink to &quot;Project Attendance System&quot;">​</a></h1><p>If your company records workers&#39; arrivals and departures in an attendance system, Buildary can import the named list of people on site straight into the daily report. On larger projects this is practically the only viable way to meet the requirement of Decree No. 131/2024 Coll., Annex 12, to keep a nominal list of persons present on the project.</p><p>You set up the connection yourself: first add the attendance system to your <a href="/buildary-help-preview/en/firstofall/domain">company domain</a>, then select it in each diary. One domain can have several attendance systems connected – for example when each project uses a different one.</p><h2 id="supported-systems" tabindex="-1">Supported systems <a class="header-anchor" href="#supported-systems" aria-label="Permalink to &quot;Supported systems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Attendance system</th><th>Credentials</th></tr></thead><tbody><tr><td><strong>Convision</strong>, <strong>AdamAssistant</strong>, <strong>Fingera</strong></td><td>username and password</td></tr><tr><td><strong>Sysdo</strong>, <strong>Sysdo grouped</strong>, <strong>WinPak</strong></td><td>API key</td></tr></tbody></table><p>You get the credentials from the supplier of your attendance system. If you would like to connect a different system, write to us at <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li><strong>Domain Administration</strong> permission in the domain – without it you won&#39;t see the <strong>Attendance Settings</strong> tab. See <a href="/buildary-help-preview/en/diary/userpermissions">User Permissions</a>.</li><li>The credentials for the attendance system (see the table above).</li><li><strong>Diary Administration</strong> permission to select the system in a diary.</li></ul><h2 id="add-an-attendance-system-to-the-domain" tabindex="-1">Add an attendance system to the domain <a class="header-anchor" href="#add-an-attendance-system-to-the-domain" aria-label="Permalink to &quot;Add an attendance system to the domain&quot;">​</a></h2><ol><li>In the left panel, click the globe icon to open the list of domains, and open your domain with the edit icon.</li><li>Go to the <strong>Attendance Settings</strong> tab and click <strong>New Attendance System</strong>.</li><li>Select the <strong>Attendance Type</strong> and enter a <strong>Connection Name</strong>.</li><li>Fill in the credentials and click <strong>Save</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Naming the connection</p><p>The <strong>Connection Name</strong> is what you will see when selecting the system in a diary. Choose names that are easy to tell apart, for example &quot;Sysdo – Ostrava&quot; and &quot;Convision – Brno&quot;.</p></div><h3 id="check-on-saving" tabindex="-1">Check on saving <a class="header-anchor" href="#check-on-saving" aria-label="Permalink to &quot;Check on saving&quot;">​</a></h3><p>When you click <strong>Save</strong>, Buildary not only stores the details but also tries to call your attendance system:</p><ul><li><strong>It works</strong> – the window closes and a confirmation appears.</li><li><strong>It fails</strong> – the window stays open with an error message asking you to check the details you entered. Correct them and save again.</li></ul><p>Required fields that are left empty are marked in red.</p><h3 id="projects-with-different-systems" tabindex="-1">Projects with different systems <a class="header-anchor" href="#projects-with-different-systems" aria-label="Permalink to &quot;Projects with different systems&quot;">​</a></h3><p>Add several connections to the domain and select the right one in each diary. You no longer need to move a project to another domain because it uses a different attendance system.</p><h2 id="edit-or-remove-a-connection" tabindex="-1">Edit or remove a connection <a class="header-anchor" href="#edit-or-remove-a-connection" aria-label="Permalink to &quot;Edit or remove a connection&quot;">​</a></h2><ul><li><strong>Edit</strong> – open the connection in the list on the <strong>Attendance Settings</strong> tab and change its name, type or credentials. For security reasons, the saved password or API key is never shown; if you leave it empty when editing, the original value is kept.</li><li><strong>Remove</strong> – a connection that a diary uses cannot be removed. First select a different system in that diary, or switch attendance off there.</li></ul><h2 id="select-the-attendance-system-in-a-diary" tabindex="-1">Select the attendance system in a diary <a class="header-anchor" href="#select-the-attendance-system-in-a-diary" aria-label="Permalink to &quot;Select the attendance system in a diary&quot;">​</a></h2><p>Open <strong>Diary Settings</strong>, <strong>Basic</strong> tab. The attendance part is shown only when the project&#39;s domain has at least one connection and you have <strong>Diary Administration</strong> permission.</p><ol><li>Select the <strong>attendance system</strong> – the list shows the connections by the names given in the domain settings.</li><li>Select the terminal (project) from that system&#39;s list. For <strong>Sysdo</strong> and <strong>Sysdo grouped</strong>, type the project identifier into the text field instead.</li><li>Optionally fill in <strong>Filter by Contractor ID</strong> – only people from these companies (by company ID, IČO) are imported and the rest are filtered out. Leave it empty to import everyone.</li><li>Save the settings.</li></ol><p>The <strong>All</strong> terminals option is available only for Sysdo.</p><h2 id="import-attendance-into-the-diary" tabindex="-1">Import attendance into the diary <a class="header-anchor" href="#import-attendance-into-the-diary" aria-label="Permalink to &quot;Import attendance into the diary&quot;">​</a></h2><p>Once the diary is connected, an import button appears in the <strong>Labour</strong> section of the daily report, with two options:</p><ul><li><strong>Import</strong> – imports that day&#39;s attendance according to the diary settings.</li><li><strong>Import with selection</strong> – first lists the companies that have at least one worker on site that day. Tick the ones whose attendance you want to import. This is useful when you keep a diary for only part of a project but the attendance terminal is shared by the whole project.</li></ul><figure class="shot" style="--w:640px;"><img src="'+s+'" alt="Labour section with the attendance import menu open" loading="lazy"><figcaption>The import menu, here for a Convision connection.</figcaption></figure><p>Records imported from an attendance system are marked with an icon, so you can easily tell them apart from records entered by hand. The icon doesn&#39;t say which system a record came from.</p><h2 id="if-something-doesn-t-work" tabindex="-1">If something doesn&#39;t work <a class="header-anchor" href="#if-something-doesn-t-work" aria-label="Permalink to &quot;If something doesn&#39;t work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>I can&#39;t see the <strong>Attendance Settings</strong> tab.</td><td>You don&#39;t have <strong>Domain Administration</strong> permission in the domain. Ask your domain administrator.</td></tr><tr><td>The attendance part is missing from Diary Settings.</td><td>The project&#39;s domain has no connection yet, or you don&#39;t have <strong>Diary Administration</strong> permission in the diary.</td></tr><tr><td>The connection can&#39;t be saved.</td><td>Check the credentials and whether the attendance system is available. If needed, contact its supplier.</td></tr><tr><td>The connection can&#39;t be removed.</td><td>A diary uses it. In that diary&#39;s settings, select a different system or switch attendance off first.</td></tr></tbody></table><p>Need help? Write to <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p>',31)])])}const g=e(r,[["render",i]]);export{p as __pageData,g as default};
